//autogenerated:yes
//nolint:revive,govet,errcheck
package asluav_test

import (
	"testing"

	"github.com/stretchr/testify/require"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/asluav"
)

func TestEnum_MAV_CMD(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.MAV_CMD
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.MAV_CMD_NAV_WAYPOINT.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.MAV_CMD
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.MAV_CMD_NAV_WAYPOINT, dec)
	})
}
